function @@proc@@(p_qty in number, p_cap in number) return varchar2 is
  l_label varchar2(20) := 'normal';
begin
  <<outer>>
  begin
    if p_qty > /* hard limit */ @@num@@ then -- @expect
      return 'over';
    end if;
    declare
      l_k number := p_cap;
    begin
      l_label := case when l_k >= @@num@@ then 'cap' else l_label end; -- @expect
    end;
  end outer;
  if p_qty - p_cap = @@num@@ then -- @expect
    l_label := 'exact';
  end if;
  return l_label;
end @@proc@@;

procedure @@proc@@(p_n in number) is
  l_acc number := 0;
begin
	for i in 1 .. @@num@@ loop -- @expect
		l_acc := l_acc + i;
		exit when l_acc > @@num@@; -- @expect
	end loop;
  l_acc := case p_n when @@num@@ then 1 else 0 end; -- @expect
  dbms_output.put_line(l_acc);
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_n number := 0;
begin
  -- the status '@@str@@' is set by the batch job
  update @@tab@@ set @@col@@ = '@@str@@' where id = p_id; -- @expect
  dbms_output.put_line(case when sql%rowcount > 0 then '@@str@@' else 'none' end); -- @expect
  @@proc2@@(p_id, '@@str@@'); -- @expect
  l_n := sql%rowcount;
end @@proc@@;

function @@proc@@(p_a in number, p_b in number, p_s in varchar2) return varchar2 is
  l_r varchar2(100);
begin
  l_r := p_s ||
         '@@str@@'; -- @expect
  if p_a > @@num@@ then -- @expect
    l_r := l_r || '@@str@@'; -- @expect
  elsif p_b > @@num@@ then -- @expect
    l_r := nvl(l_r, '@@str@@'); -- @expect
  elsif p_a + p_b < @@num@@ then -- @expect
    l_r := null;
  end if;
  return l_r;
end @@proc@@;

