function @@proc@@(p_qty in number) return varchar2 is
begin
  /* threshold @@num@@ comes from the contract */
  if p_qty > @@num@@ then -- above @@num@@
    return 'limit @@num@@ exceeded';
  end if;
  if p_qty = @@num@@ then
    return 'at limit';
  end if;
  return 'ok';
end @@proc@@;

procedure @@proc@@(p_a in varchar2, p_out out varchar2) is
begin
  p_out := '';
  if p_a = 'Open_@@str@@' then
    p_out := p_out || ',' || 'o';
  elsif p_a = 'open_@@str@@' then
    p_out := p_out || ',' || 'p';
  elsif p_a = 'OPEN_@@str@@' then
    p_out := p_out || ',' || 'q';
  end if;
  if length(p_out) > 1 then
    p_out := substr(p_out, 1, length(p_out) - 1);
  end if;
end @@proc@@;

function @@proc@@(p_a in number, p_s in varchar2) return number is
  l_n number := 0;
begin
  if p_a > @@num@@ then l_n := l_n + 1; end if;
  if p_a < @@num2@@ then l_n := l_n + 1; end if;
  if p_s = '@@str@@' then l_n := l_n + 1; end if;
  if p_s = '@@str2@@' then l_n := l_n + 1; end if;
  if p_a = @@num@@ then l_n := l_n + 1; end if;
  if p_a <> @@num2@@ then l_n := l_n + 1; end if;
  if p_s <> '@@str@@' then l_n := l_n + 1; end if;
  if p_s <> '@@str2@@' then l_n := l_n + 1; end if;
  return l_n;
end @@proc@@;

function @@proc@@(p_a in number) return number is
  l_r number := 0;
begin
  l_r := p_a * /* @@num@@ */ 1;
  -- legacy: p_a > @@num@@ or p_a < @@num@@
  /* @@num@@ appears in the spec only */
  if l_r > @@num@@ then
    l_r := 0;
  end if;
  return l_r;
end @@proc@@;

procedure @@proc@@ is
  l_seen number := 0;
begin
  for r in (select ol."Qty @@num@@" as a, ol."Amt @@num@@" as b, ol."Tax @@num@@" as c
              from "Order Line" ol) loop
    l_seen := l_seen + r.a + r.b + r.c;
  end loop;
  dbms_output.put_line(l_seen);
end @@proc@@;
